 19	export function getDashboardFileStatus(agentDir: string): DashboardFileStatus {
 20		const fileExists = (name: string): boolean => {
 21			const filePath = join(agentDir, name);
 22			try {
 23				return existsSync(filePath) && statSync(filePath).isFile();
 24			} catch {
 25				return false;
 26			}
 27		};
