 11	export async function runImportFlow(): Promise<{ imported: string[] } | undefined> {
 12		const defaultDir = path.join(os.homedir(), ".pi", "agent");
 13		const choice = await vscode.window.showQuickPick(
 14			[
 15				{ label: "Import from ~/.pi (config + sessions)", detail: "Copy settings.json, auth.json, models.json and the sessions/ folder" },
 16				{ label: "Import from ~/.pi (config only)", detail: "Copy settings.json, auth.json, models.json" },
 17				{ label: "Import from another folder (config + sessions)…", detail: "Pick a directory containing a pi agent config" },
 18				{ label: "Import from another folder (config only)…", detail: "Pick a directory containing settings.json / auth.json / models.json" },
 19			],
 20			{ placeHolder: "Import pi configuration into CodePi's storage" },
 21		);
 22		if (!choice) return undefined;
 23	
 24		let source = defaultDir;
 25		let includeSessions = false;
 26		if (choice.label.startsWith("Import from ~/.pi (config + sessions)")) {
 27			includeSessions = true;
 28		} else if (choice.label.startsWith("Import from ~/.pi (config only)")) {
 29			/* defaults */
 30		} else {
 31			const picked = await vscode.window.showOpenDialog({
 32				canSelectFiles: false,
 33				canSelectFolders: true,
 34				canSelectMany: false,
 35				openLabel: "Select config folder",
 36				title: "Select a folder containing pi config (settings.json / auth.json / models.json)",
 37				defaultUri: vscode.Uri.file(defaultDir),
 38			});
 39			if (!picked || picked.length === 0) return undefined;
 40			source = picked[0].fsPath;
 41			includeSessions = choice.label.includes("config + sessions");
 42		}
 43	
 44		return importLegacyConfig(source, getAgentDir(), { includeSessions });
 45	}

